head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.ibx_openPopup_onclick = function(e) {
    requires("uiplugin.popup");
    var paramData = {
        parentPopupId: "",
        rowData: WebSquare.wUnit.getObjById('dlt_memberList').getRowJSON(0)
    };
    var dataObj = {
        type: "json", // 데이터 타입. "xml","string","json","array" 
        data: paramData, // 전달 데이터 객체. 
        name: "paramData" // 변수명. popup에서 $w.getParameter( "rowObj" )로 깨내올 수 있다. 
    };
    var opts = {
        "id": "popup_wframe1",
        "type": "window",
        "width": "700px",
        "height": "250px",
        "top": 150,
        "left": 150,
        "popupName": "Popup1",
        "modal": false,
        "useIFrame": true,
        "dataObject": dataObj,
        "title": "focusTest",
        //			"alwaysOnTop" : false,
        "useControl": true,
        "controls": {
            "minimize": true,
            "maximize": true,
            "close": true
        },
        //			"foldSize" :{
        //				"width" : 200
        //			},					
        "foldOnMinimized": true,
        "frameMode": "wframe"
    };
    $w.openPopup("popup_modal_false_WEFF-397_(WSQ-3743)_wframe1.xml", opts);
    //console.log("[Open popup_wframe1]");
};
scwin.getZIndex = function() {
    return parseInt(popup_wframe1.getStyle("z-index")) <= parseInt(popup_wframe2.getStyle("z-index"));
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('ibx_openPopup').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "popup_wframe1_wframe_ibx_openPopup.click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("assert", "scwin.getZIndex()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
